<script setup lang="ts">
defineProps<{project:any;currentProject:number|null;currentDepartment:number|null}>();const emit=defineEmits(['project','board','preview']);
</script>
<template><details class="pms-tree-node pms-hierarchy-project" :open="project.id===currentProject"><summary><button class="pms-tree-label" :title="project.name" @click.stop="emit('project',project.id)">{{project.name}}</button><button class="pms-tree-eye" :aria-label="'View project board: '+project.name" :title="'View all '+project.name+' tasks'" @click.stop.prevent="emit('preview','project',project.id)"><i class="ti ti-eye" aria-hidden="true"></i></button><i class="ti ti-chevron-right pms-tree-chevron" aria-hidden="true"></i></summary><div class="pms-tree-children"><button v-for="d in project.departments" :key="d.id" class="pms-tree-node pms-hierarchy-department" :title="d.dept_name" :class="{active:project.id===currentProject&&d.id===currentDepartment}" @click="emit('board',project.id,d.id)"><i aria-hidden="true" class="ti ti-layout-kanban"></i><span>{{d.dept_name}}</span></button><p v-if="!project.departments.length" class="small text-muted pms-tree-node">No departments assigned.</p></div></details></template>
